SELECT SUM(CASE WHEN DAYS_SINCE_LAST_CHANGE >= 90 THEN TOTAL_BYTES ELSE 0 END) AS "STORAGE_STALE_TABLE_BYTES" FROM (SELECT "ID" AS TABLE_ID, "TABLE_NAME" AS TABLE_NAME, "TABLE_CATALOG" AS DATABASE_NAME, "TABLE_SCHEMA" AS SCHEMA_NAME, "CLONE_GROUP_ID" AS CLONE_GROUP_ID, "ACTIVE_BYTES" AS ACTIVE_BYTES, "TIME_TRAVEL_BYTES" AS TIME_TRAVEL_BYTES, "FAILSAFE_BYTES" AS FAILSAFE_BYTES, "RETAINED_FOR_CLONE_BYTES" AS RETAINED_FOR_CLONE_BYTES, "ACTIVE_BYTES" + "TIME_TRAVEL_BYTES" + "FAILSAFE_BYTES" + "RETAINED_FOR_CLONE_BYTES" AS TOTAL_BYTES, "RETENTION_TIME" AS RETENTION_DAYS, "IS_TRANSIENT" AS IS_TRANSIENT, COALESCE("DELETED", FALSE) AS IS_DELETED, (TRY_CAST("TABLE_CREATED" AS TIMESTAMP)) AS TABLE_CREATED_AT, (TRY_CAST("TABLE_DROPPED" AS TIMESTAMP)) AS TABLE_DROPPED_AT, (TRY_CAST("TABLE_ENTERED_FAILSAFE" AS TIMESTAMP)) AS ENTERED_FAILSAFE_AT, (TRY_CAST("_LOADED_AT" AS TIMESTAMP)) AS SNAPSHOT_AT, (CAST(CASE WHEN (86400) = 0 OR (86400) IS NULL THEN NULL ELSE CAST(((DATE_DIFF('SECOND', (TRY_CAST("TABLE_CREATED" AS TIMESTAMP)), (TRY_CAST("_LOADED_AT" AS TIMESTAMP))))) AS DECIMAL(38, 15)) / CAST((86400) AS DECIMAL(38, 15)) END AS DECIMAL(38, 15))) AS DAYS_SINCE_LAST_CHANGE FROM table_storage_metrics) AS base ORDER BY "STORAGE_STALE_TABLE_BYTES" DESC LIMIT 100
